            auto victim = entries.begin();
            for (auto x = entries.begin(); x != entries.end(); ++x)
                if (make_pair(x->second[1], x->second[2]) < make_pair(victim->second[1], victim->second[2])) victim = x;
            entries.erase(victim);
        }
        entries[key] = {value, 1, clock++};
    }
