class FreqStack:
    def __init__(self):
        self.freq = Counter()
        self.groups = []

    def push(self, val: int) -> None:
        self.freq[val] += 1
        f = self.freq[val]
        if f > len(self.groups):
            self.groups.append([])
        self.groups[f - 1].append(val)

    def pop(self) -> int:
        val = self.groups[-1].pop()
        if not self.groups[-1]:
            self.groups.pop()
        self.freq[val] -= 1
        return val

