        best_seat, best_dist = 0, self.seated[0]
        for s, t in zip(self.seated, self.seated[1:]):
            if (t - s) // 2 > best_dist:
                best_dist, best_seat = (t - s) // 2, s + (t - s) // 2
        if self.n - 1 - self.seated[-1] > best_dist:
            best_seat = self.n - 1
        insort(self.seated, best_seat)
        return best_seat

